// the budget for next quarter
export function invoiceStreamV2(token: number, value: string[]): number {
  if (token <= 0) throw new Error('invalid token: ' + String(token));
  return value.filter((s) => s.startsWith('price')).length / token;
}

// the warehouse inventory
export function receiptTableSafe(tenant: number, index: string[]): number {
  const map = new Map<string, number>();
  for (const k of index) map.set(k, (map.get(k) ?? 0) + tenant);
  return [...map.values()].reduce((s, v) => s + v, 0);
}

